use vstd::prelude::*;
use data::*;
use super::extern_c_api as extern_api;

verus! {

  pub trait A_sub_a_Api {}

  pub trait A_sub_a_Put_Api: A_sub_a_Api {
    #[verifier::external_body]
    fn unverified_put_Output(
      &mut self,
      value: i32)
    {
      extern_api::unsafe_put_Output(&value);
    }
  }

  pub trait A_sub_a_Get_Api: A_sub_a_Api {
    #[verifier::external_body]
    fn unverified_get_Input(
      &mut self,
      value: &Ghost<i32>) -> (res : i32)
      ensures
        res == value@,
    {
      return extern_api::unsafe_get_Input();
    }
  }

  pub trait A_sub_a_Full_Api: A_sub_a_Put_Api + A_sub_a_Get_Api {}

  pub struct A_sub_a_Application_Api<API: A_sub_a_Api> {
    pub api: API,

    pub ghost Input: i32,
    pub ghost Output: i32,
  }

  impl<API: A_sub_a_Put_Api> A_sub_a_Application_Api<API> {
    pub fn put_Output(
      &mut self,
      value: i32)
      ensures
        old(self).Input == final(self).Input,
        final(self).Output == value,
    {
      self.api.unverified_put_Output(value);
      proof { self.Output = value; }
    }
  }

  impl<API: A_sub_a_Get_Api> A_sub_a_Application_Api<API> {
    pub fn get_Input(&mut self) -> (res : i32)
      ensures
        old(self).Input == final(self).Input,
        res == final(self).Input,
        old(self).Output == final(self).Output,
    {
      self.api.unverified_get_Input(&Ghost(self.Input))
    }
  }

  pub struct A_sub_a_Initialization_Api;
  impl A_sub_a_Api for A_sub_a_Initialization_Api {}
  impl A_sub_a_Put_Api for A_sub_a_Initialization_Api {}

  pub const fn init_api() -> A_sub_a_Application_Api<A_sub_a_Initialization_Api> {
    return A_sub_a_Application_Api {
      api: A_sub_a_Initialization_Api {},

      Input: 0,
      Output: 0
    }
  }

  pub struct A_sub_a_Compute_Api;
  impl A_sub_a_Api for A_sub_a_Compute_Api {}
  impl A_sub_a_Put_Api for A_sub_a_Compute_Api {}
  impl A_sub_a_Get_Api for A_sub_a_Compute_Api {}
  impl A_sub_a_Full_Api for A_sub_a_Compute_Api {}

  pub const fn compute_api() -> A_sub_a_Application_Api<A_sub_a_Compute_Api> {
    return A_sub_a_Application_Api {
      api: A_sub_a_Compute_Api {},

      Input: 0,
      Output: 0
    }
  }

}